"""Writes docs/03_results/V2_RESULTS.md from ``results/results.json`` (one section per hypothesis: verdict, numbers, intervals, what the result does and does not show). No number is typed here; every number is read from a v2 key.
Origins: A and D MEASURED_SOFTWARE (176 NHTSA crash tests, mostly high-speed barrier tests, not representative of all real crashes), B, F2 and H-E1 SIMULATED (every value an assumption of the simulator; the duty limit is not verified for India),
H-E2 and F1 ANALYTICAL.
"""
from __future__ import annotations

import json
from pathlib import Path

R = {e["name"]: e for e in json.loads(Path("results/results.json").read_text(encoding="utf-8"))}
OUT = Path("docs/03_results/V2_RESULTS.md")


def v(k):
    return R[k]["value"]


def f(k, d=3):
    x = v(k)
    return str(x) if isinstance(x, str) else f"{x:.{d}f}"


def ci(k, d=3):
    return f"{f(k, d)} [{f(k + '_lo', d)} to {f(k + '_hi', d)}]"


def tab(h, rows):
    out = ["| " + " | ".join(h) + " |", "|" + "|".join("---" for _ in h) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out) + "\n"


def verdict(h):
    return f"**{v(f'v2.holm.verdict.{h}')}** ({R[f'v2.holm.verdict.{h}']['notes']}; origin {R[f'v2.holm.verdict.{h}']['origin']})"


def main() -> None:
    L: list[str] = []
    a = L.append
    a("# v2 results: five algorithm studies\n")
    a("Generated by `python -m crashguard.v2_docs` from `results/results.json`; plan and rules: `docs/02_preregistration/PREREGISTRATION_V2.md` (the initial commit of the branch `v2-algorithms`, written before any v2 result). Every number below is a `v2.` key. "
      "Study A and D numbers are MEASURED_SOFTWARE on 176 NHTSA crash tests (mostly high-speed barrier tests, not representative of all real crashes). Studies B, F2 and the capacity simulation of Study E (H-E1) are SIMULATED: every channel and traffic value is an assumption of the simulator and the 1% duty limit is not verified for India. The forgery work factor of Study E (H-E2) and the cost model F1 are ANALYTICAL. "
      "Anything not in the preregistration is labelled EXPLORATORY. Deviations and mistakes are in `docs/07_log/DECISIONS.md` (run 1 of Study A used in-sample residuals for the difficulty model and was re-run; both runs are kept).\n")
    a("## Verdicts\n")
    rows = []
    for h in ("H-A1", "H-A2", "H-A3", "H-B1", "H-B2", "H-B3", "H-D1", "H-D2", "H-E1", "H-E2", "H-F1", "H-F2"):
        kp, kh = f"v2.holm.{h}.p_raw", f"v2.holm.{h}.p_holm"
        rows.append([h, v(f"v2.holm.verdict.{h}"), R[f"v2.holm.verdict.{h}"]["notes"], f(kp, 4) if kp in R else "no p-value (rule)", f(kh, 4) if kh in R else "no p-value (rule)", R[f"v2.holm.verdict.{h}"]["origin"]])
    a(tab(["Hypothesis", "Verdict", "Reason", "Raw p", "Holm-adjusted p", "Origin"], rows))
    a("One Holm correction over the nine hypotheses with a statistical test (H-A1, H-A2, H-A3, H-B1, H-B2, H-D1, H-D2, H-E1, H-F2). The bootstrap p-value has a floor of 0.001 with 1,000 resamples.\n")

    # ---------------------------------------------------------------- A
    a("## Study A: tail-aware clipping estimator (MEASURED_SOFTWARE)\n")
    a("### H-A1: lower 90th-percentile delta-V error than fill + ridge at +-16 g\n")
    a(f"Verdict: {verdict('H-A1')}.\n")
    rows = []
    for sp, nm in (("R", "R (repeated grouped 5-fold, 132 make/model groups)"), ("G", "G (vehicle-group hold-out)"), ("A", "A (make/model hold-out)"), ("O", "O (original test-number rule)")):
        rows.append([nm, ci(f"v2.a.hA1.{sp}.p90_reduction_Mplus_minus_QR", 2)])
    a(tab(["Split", "p90 of fill + ridge minus p90 of the tail-aware estimator, points [95%]"], rows))
    a(f"Splits with a point reduction of at least 5 points: {f('v2.a.hA1.n_splits_with_5pt_gain', 0)} of 4. The preregistered primary estimator is the median quantile boosting model (QR); the plain gradient-boosting model (GBR) has a lower p90 than QR on split R (see the table); it is EXPLORATORY. Of the three fixed splits (G, A, O) only O has its whole interval above zero; G and O have point reductions above 5 points. Against the triangle fit the reduction on split R is {ci('v2.a.R.r16.paired.TRI_minus_QR.p90', 1)} points (interval includes zero), so the tail-aware estimator is not shown better than the triangle fit alone; ridge on all features (EXPLORATORY) has a 90th-percentile error of {f('v2.a.R.r16.RIDGE.p90', 1)}% against {f('v2.a.R.r16.QR.p90', 1)}% for the tail-aware estimator and was not compared with it directly.\n")
    rows = []
    for m, nm in (("B", "plain"), ("SP", "spline"), ("M", "fill"), ("M+", "fill + ridge"), ("TRI", "triangle fit (our implementation of the idea)"), ("GP", "Gaussian-process fill (our implementation of the idea)"), ("AVG", "cost-weighted pulse-family average"),
                  ("RIDGE", "ridge on all features (EXPLORATORY)"), ("GBR", "gradient boosting (EXPLORATORY)"), ("QR", "tail-aware, median quantile model (primary)")):
        rows.append([nm, ci(f"v2.a.R.r16.{m}.median", 1), ci(f"v2.a.R.r16.{m}.p90", 1), ci(f"v2.a.R.r16.{m}.p95", 1), ci(f"v2.a.R.r16.{m}.w10", 3)])
    a("Split R, +-16 g, 100 Hz (absolute delta-V error, grouped bootstrap):\n")
    a(tab(["Estimator", "Median error (%)", "p90 (%)", "p95 (%)", "Within 10%"], rows))
    a("The tail-aware estimator also has a lower median error than fill + ridge. The new estimators are fitted on clipping descriptors and pulse-family features of the same 176 tests the earlier ridge used (always on the training tests of the fold); nothing here was tested on a vehicle outside the 176 tests or on a real saturated sensor, and the 90th-percentile error of every estimator is still large.\n")
    a("### H-A2: adaptive conformal intervals narrower in the lowest clipped-fraction tercile\n")
    a(f"Verdict: {verdict('H-A2')}.\n")
    rows = []
    for k, nm in (("i", "plain split conformal"), ("ii", "conformalized quantile regression"), ("iii", "normalised score (adaptive)")):
        rows.append([nm, ci(f"v2.a.a5.r16.{k}.coverage", 3), f(f"v2.a.a5.r16.{k}.width_kmh", 1), f(f"v2.a.a5.r16.{k}.bin_low.coverage", 3), f(f"v2.a.a5.r16.{k}.bin_low.width_rel", 3), f(f"v2.a.a5.r16.{k}.bin_mid.width_rel", 3), f(f"v2.a.a5.r16.{k}.bin_high.width_rel", 3)])
    a(tab(["Interval", "Coverage on held-out vehicles [95%]", "Mean width (km/h)", "Coverage, lowest tercile", "Median relative width, lowest", "mid", "high"], rows))
    a(f"Lowest tercile, mean relative width of the adaptive interval minus the plain one: {ci('v2.a.hA2.low_tercile.relwidth_iii_minus_i', 3)} (positive = wider). Coverage of the adaptive intervals: {f('v2.a.hA2.coverage_iii', 3)}. The relative widths in the table are medians; the mean difference above is dominated by a few very wide intervals.\n"
      f"The adaptive intervals fix the under-coverage of the plain intervals in the lowest tercile but do so by being wider there, not narrower. In the middle and highest terciles they are narrower (median relative width {f('v2.a.a5.r16.iii.bin_mid.width_rel', 2)} and {f('v2.a.a5.r16.iii.bin_high.width_rel', 2)} against {f('v2.a.a5.r16.i.bin_mid.width_rel', 2)} and {f('v2.a.a5.r16.i.bin_high.width_rel', 2)}) with coverage {f('v2.a.a5.r16.iii.bin_mid.coverage', 2)} and {f('v2.a.a5.r16.iii.bin_high.coverage', 2)}. " f"The tests that never clip at +-16 g ({f('v2.a.a5.r16.iii.bin_none.n', 0)} test-repeats) are covered by only {f('v2.a.a5.r16.iii.bin_none.coverage', 2)} of the intervals of every variant: the plain estimate is far from the reference for them.\n")
    a("### H-A3: deterministic bounds contain the reference delta-V\n")
    a(f"Verdict: {verdict('H-A3')}.\n")
    rows = []
    for rg in (16, 32, 64):
        rows.append([f"+-{rg} g", ci(f"v2.a.a2.r{rg}.containment", 3), f(f"v2.a.a2.r{rg}.n_saturated", 0), f(f"v2.a.a2.r{rg}.lower_exceeds_ref_1p00", 0), f(f"v2.a.a2.r{rg}.upper_below_ref", 0), f(f"v2.a.a2.r{rg}.width_kmh_mean", 1)])
    a(tab(["Range", "Containment [95%]", "Tests with a clipped sample", "Plain estimate above the reference", "Upper bound below the reference", "Mean width (km/h)"], rows))
    a("The lower-bound statement (the plain estimate cannot exceed the true delta-V) holds for all but {f('v2.a.a2.r16.lower_exceeds_ref_1p00', 0)} of 176 tests at +-16 g; at +-32 g and +-64 g it fails for {f('v2.a.a2.r32.lower_exceeds_ref_1p00', 0)} and {f('v2.a.a2.r64.lower_exceeds_ref_1p00', 0)} tests (the severity code's pulse end and the reference integration window differ), so it is not a guarantee. The upper bound from the pulse-family fits is below the reference for {f('v2.a.a2.r16.upper_below_ref', 0)} tests at +-16 g, so the bounds do not contain the reference at the stated rate.\n")
    a("### A6 abstention flag (EXPLORATORY)\n")
    rows = []
    for rg in (16, 32, 64):
        rows.append([f"+-{rg} g", f(f"v2.a.a6.r{rg}.share_flagged", 3), f(f"v2.a.a6.r{rg}.unflagged.p90_err", 1) if f"v2.a.a6.r{rg}.unflagged.p90_err" in R else "n/a", f(f"v2.a.a6.r{rg}.flagged.p90_err", 1) if f"v2.a.a6.r{rg}.flagged.p90_err" in R else "n/a"])
    a(tab(["Range", "Share flagged", "p90 error, unflagged (%)", "p90 error, flagged (%)"], rows))

    # ---------------------------------------------------------------- D
    a("## Study D: clip-onset early severity flag (MEASURED_SOFTWARE)\n")
    a(f"H-D1: {verdict('H-D1')}.\n")
    a(f"H-D2: {verdict('H-D2')}.\n")
    rows = []
    for rn, nm in (("D2", "clip-onset flag (D2)"), ("II", "running delta-V reaches 40 km/h (the severity analogue of the early-exit rule)"), ("I", "full-pulse class of the earlier estimator"), ("PK", "early-peak threshold (no clipping logic)")):
        rows.append([nm, ci(f"v2.d.R.r16.f100.{rn}.detection", 3), ci(f"v2.d.R.r16.f100.{rn}.over_triage", 3), ci(f"v2.d.R.r16.f100.{rn}.median_time_saved_ms", 0) if f"v2.d.R.r16.f100.{rn}.median_time_saved_ms" in R else "n/a"])
    a("Split R, +-16 g, 100 Hz:\n")
    a(tab(["Rule", "Detection of Severe or Critical", "Over-triage", "Median time saved (ms)"], rows))
    a(f"Under-triage of the clip-onset flag minus that of the analogue: {ci('v2.d.hD1.under_triage_D2_minus_analogue', 3)} (positive = the flag misses more). The median time saved is over the Severe or Critical tests that the flag does flag ({f('v2.d.R.r16.f100.D2.detection', 2)} of them); the analogue flags {f('v2.d.R.r16.f100.II.detection', 2)} and saves {f('v2.d.R.r16.f100.II.median_time_saved_ms', 0)} ms, so the clip-onset flag is earlier where it fires but fires less often. Share of tests that never clip at +-16 g and 100 Hz: {f('v2.d.r16.f100.share_never_clip', 3)}; those cannot be flagged this way. "
      "The early-peak rule found no setting with low over-triage because the NHTSA tests are mostly high-speed barrier tests whose early peaks are all large.\n")

    # ---------------------------------------------------------------- B
    a("## Study B: load-adaptive escalation (SIMULATED)\n")
    a(f"H-B1: {verdict('H-B1')}.\n")
    a(f"H-B2: {verdict('H-B2')}.\n")
    a(f"H-B3: {verdict('H-B3')}. The token bucket's mean gain over the burst cells is {f('v2.b.hB3.bucket_mean_gain', 4)} against {f('v2.b.hB3.best_mean_gain', 4)} for the best variant; it would fail the 80% rule as well.\n")
    VN = {"V1": "controller", "V2": "token bucket", "V3": "beacon-assisted", "V4": "severity-scaled backoff", "V5": "graceful demotion"}
    rows = []
    for vv in VN:
        rows.append([VN[vv], v(f"v2.b.tuned.{vv}"), f(f"v2.b.hB1.{vv}.n_cells_gain_3pts", 0), f(f"v2.b.hB1.{vv}.mean_gain_burst_cells", 4), f(f"v2.b.cells_beating_matched.{vv}", 0)])
    a(tab(["Variant", "Tuned parameters", "Burst cells with a gain of 3 points and an interval above zero (of 10)", "Mean gain over the burst cells", "Cells of 18 with the whole interval above zero"], rows))
    cellsb = ["burst_base", "burst_burst10", "burst_burst60", "burst_cars50", "burst_cars200", "burst_sf9", "burst_capnone", "loadedburst_base", "loadedburst_cars200", "loadedburst_sf9"]
    rows = []
    for c in cellsb:
        rows.append([c] + [ci(f"v2.b.gain.{c}.{vv}.reach10_critical", 3) for vv in VN])
    a("Critical reach within 10 s, variant minus its matched fixed lowered-threshold baseline (paired by seed, 40 seeds), burst cells:\n")
    a(tab(["Cell"] + list(VN.values()), rows))
    rows = []
    for c in ("steady_base", "steady_cars200", "steady_loss30", "single_loss60", "mixed_cars200"):
        rows.append([c] + [ci(f"v2.b.gain.{c}.{vv}.reach10_critical", 3) for vv in VN])
    a("The same, steady cells, the single-car cell and the mixed cell:\n")
    a(tab(["Cell"] + list(VN.values()), rows))
    below = [(c, vv, ci(f'v2.b.gain.{c}.{vv}.reach10_critical', 3)) for c in cellsb + ['steady_base', 'steady_cars200', 'steady_loss30', 'single_loss60', 'mixed_cars200'] for vv in VN if v(f'v2.b.gain.{c}.{vv}.reach10_critical_hi') < 0]
    a('Cells in which a variant is WORSE than its matched baseline with the whole interval below zero: ' + ('; '.join(f'{c}, {VN[vv]} {x}' for c, vv, x in below) if below else 'none') + '. For H-B2: no whole interval of harm lies above 2 points, but the upper 95% bound of the harm exceeds 2 points for some variants and cells (for example the beacon variant in the steady cell with loss 0.3 and graceful demotion in the single-car cell).\n')
    a(f"Matching: the mean absolute difference in realised escalation between a variant and its baseline over all cells is small (per-cell values in `v2.b.match.*`). Runs above the duty limit: {f('v2.b.duty.runs_exceeding_limit', 0)}. "
      "As written before the runs, the unloaded burst cells hold almost no competing non-severe escalations and the per-car controller and bucket have no history to act on; the loaded cells and the mixed cell are where the competition exists.\n")

    # ---------------------------------------------------------------- E
    a("## Study E: authentication-tag length against capacity\n")
    a(f"H-E1 (SIMULATED): {verdict('H-E1')}. Gain of the 4-byte tag over the 8-byte tag in critical reach within 10 s, P2, 7 unloaded burst cells: {ci('v2.e.hE1.gain_t4_minus_t8', 4)}.\n")
    a(f"H-E2 (ANALYTICAL): {verdict('H-E2')}. At 8 bytes the attempts for a forgery probability of 1e-6 are 2^{f('v2.e.hE2.log2_attempts_for_1e6_t8', 1)} and the expected attempts 2^{f('v2.e.forgery.t8.log2_expected_attempts', 0)}. The smallest tag with both work factors above 2^32 is {f('v2.e.e3.smallest_tag_bytes_above_2p32', 0)} bytes (analytic). The work factor is a count of attempts and is not capped by the duty limit; the years in the table are the time for a single duty-limited transmitter, not for an attacker.\n")
    rows = []
    for t in (4, 6, 8, 12, 16):
        rows.append([t, f(f"v2.e.forgery.t{t}.log2_expected_attempts", 0), f(f"v2.e.forgery.t{t}.sf7.log2_attempts_for_1e6", 1), f(f"v2.e.forgery.t{t}.sf9.attempts_per_hour_dutycap", 0), f(f"v2.e.forgery.t{t}.sf9.years_expected_dutycap", 3),
                     f(f"v2.e.cells.P2.t{t}.reach10_critical", 4), f(f"v2.e.cells.P2.t{t}.node_air_share", 4)])
    a(tab(["Tag bytes", "log2 expected attempts", "log2 attempts for 1e-6", "Frames per hour at 1% duty, SF9", "Expected years to one forgery at that rate, SF9", "Critical reach within 10 s (P2, mean of 10 burst cells)", "Node airtime share of the allowance"], rows))
    a("The duty limit does not bind an attacker; the uncapped rate is in `v2.e.forgery.*.attempts_per_hour_uncapped`. A truncated tag is a known trade-off; no proof is claimed. The simulated gain from a 4-byte tag is small: {ci('v2.e.hE1.gain_t4_minus_t8', 4)} (about one point), below the 2 points asked for.\n")

    # ---------------------------------------------------------------- F
    a("## Study F: severity-dependent hold\n")
    a(f"H-F1 (ANALYTICAL): {verdict('H-F1')}. A positive hold is optimal when D / C_false is below {f('v2.f.hF1.ppv.crossing_d_over_cf', 1)} at the precision of the deployed forest at 0.02% prevalence ({f('v2.f.p.ppv', 4)}) and below {f('v2.f.hF1.simmix.crossing_d_over_cf', 2)} at the simulator's alert mix ({f('v2.f.p.simmix', 3)}).\n")
    rows = []
    for r in (1, 10, 100, 1000, 10000):
        rows.append([r] + [f(f"v2.f.opt.ppv.ratio{r}.class{c}", 1) for c in range(4)] + [f(f"v2.f.opt.simmix.ratio{r}.class{c}", 1) for c in range(4)])
    a(tab(["C_delay / C_false per second", "ppv: Low", "Moderate", "Severe", "Critical", "mix: Low", "Moderate", "Severe", "Critical"], rows))
    a(f"H-F2 (SIMULATED): {verdict('H-F2')}. A 2 s hold for Severe alerts reduces the share of false Severe alerts that reach the base by {ci('v2.f.hF2.relative_reduction_false_severe_reaching_base', 3)} (steady cell with false alarms at the 5% target); the change in critical reach within 10 s is {ci('v2.f.hF2.change_critical_reach10', 4)}, so a loss of up to {-float(v('v2.f.hF2.change_critical_reach10_lo')) * 100:.1f} points is not excluded. The delay to true Severe alerts caused by the hold is not measured in this study (it adds the hold to the time of the earliest transmission).\n")

    a("## Not run, and what the studies do not show\n")
    a("- **Study C (combination)** is NOT_RUN. It was conditional on a positive result in A or B that could supply a ranking score. B has no positive result, and the only positive result in A is the point estimator, which gives no interval width; the A5 interval widths failed H-A2. In addition, in the per-car framework each car has at most one competing escalation, so a ranking score has nothing to rank.\n"
      "- A deterministic upper bound with the stated containment, adaptive intervals that are narrower where clipping is mild, a clip-onset flag that saves 100 ms or more, load-adaptive escalation that gains 3 points, and a tag-length gain of 2 points or more were not found.\n"
      "- Nothing here was measured on a car, an ESP32 or radios.\n")
    OUT.write_text("\n".join(L), encoding="utf-8")
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
